import { Ionicons } from "@expo/vector-icons";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useMemo, useState } from "react";
import { ActivityIndicator, Image, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { fallbackProductImage } from "../catalog/catalog.view-model";
import { getVendorProducts, submitVendorProduct } from "../catalog/catalog.api";

const statuses = ["ALL", "DRAFT", "SUBMITTED", "APPROVED", "REJECTED", "ARCHIVED"] as const;

export function VendorProductsScreen() {
  const router = useRouter();
  const user = firebaseAuth?.currentUser ?? null;
  const cache = useQueryClient();
  const products = useQuery({ queryKey: ["vendor", "products"], queryFn: () => getVendorProducts(user!), enabled: Boolean(user) });
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<typeof statuses[number]>("ALL");
  const submit = useMutation({ mutationFn: (id: string) => submitVendorProduct(user!, id), onSuccess: () => cache.invalidateQueries({ queryKey: ["vendor", "products"] }) });
  const visible = useMemo(() => (products.data ?? []).filter((product) => status === "ALL" || product.status === status).filter((product) => `${product.name} ${product.brand || ""} ${product.slug} ${product.variants.map((item) => item.sku).join(" ")}`.toLowerCase().includes(search.trim().toLowerCase())), [products.data, search, status]);
  const approved = products.data?.filter((item) => item.status === "APPROVED").length ?? 0;
  const pending = products.data?.filter((item) => item.status === "SUBMITTED").length ?? 0;
  const drafts = products.data?.filter((item) => ["DRAFT", "REJECTED"].includes(item.status)).length ?? 0;
  return <Screen eyebrow="SELLER CATALOG" title="Products" description="Create, search, review and submit marketplace listings for moderation.">
    <View style={styles.summary}><Metric icon="cube-outline" label="All products" value={products.data?.length ?? 0} /><Metric icon="checkmark-circle-outline" label="Live products" value={approved} /><Metric icon="time-outline" label="In review" value={pending} /><Metric icon="create-outline" label="Needs work" value={drafts} /></View>
    <View style={styles.toolbar}><View style={styles.search}><Ionicons color={colors.muted} name="search-outline" size={19} /><TextInput accessibilityLabel="Search seller products" onChangeText={setSearch} placeholder="Search name, brand or SKU" placeholderTextColor={colors.muted} style={styles.searchInput} value={search} />{search ? <Pressable onPress={() => setSearch("")}><Ionicons color={colors.muted} name="close-circle" size={18} /></Pressable> : null}</View><Pressable onPress={() => router.push("/vendor/bulk-products")} style={styles.secondary}><Ionicons color={colors.primary} name="cloud-upload-outline" size={18} /><Text style={styles.secondaryText}>Bulk import</Text></Pressable><Pressable onPress={() => router.push("/vendor/products/add")} style={styles.primary}><Ionicons color={colors.surface} name="add" size={20} /><Text style={styles.primaryText}>Add product</Text></Pressable></View>
    <View style={styles.filters}>{statuses.map((item) => { const active = item === status; const count = item === "ALL" ? products.data?.length ?? 0 : products.data?.filter((product) => product.status === item).length ?? 0; return <Pressable key={item} onPress={() => setStatus(item)} style={[styles.filter, active && styles.filterActive]}><Text style={[styles.filterText, active && styles.filterTextActive]}>{item === "ALL" ? "All" : item.toLowerCase().replace(/^./, (letter) => letter.toUpperCase())}</Text><Text style={[styles.filterCount, active && styles.filterCountActive]}>{count}</Text></Pressable>; })}</View>
    {products.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{products.error ? <Text style={styles.error}>{products.error.message}</Text> : null}
    <View style={styles.resultsHeader}><Text style={styles.resultCount}>{visible.length} product{visible.length === 1 ? "" : "s"}</Text><Text style={styles.resultMeta}>Most recently updated first</Text></View>
    <View style={styles.grid}>{visible.map((product) => { const editable = ["DRAFT", "REJECTED"].includes(product.status); const stock = product.variants.reduce((sum, item) => sum + item.availableQuantity, 0); return <View key={product.id} style={styles.card}><Pressable onPress={() => router.push(`/vendor/products/${product.id}` as never)}><View style={styles.media}><Image source={{ uri: product.media[0]?.url || product.thumbnailUrl || fallbackProductImage }} style={styles.image} /><Text style={[styles.status, product.status === "REJECTED" && styles.rejected]}>{product.status}</Text></View><View style={styles.cardBody}><Text numberOfLines={2} style={styles.name}>{product.name}</Text><Text style={styles.brand}>{product.brand || "Unbranded"}</Text><View style={styles.priceRow}><Text style={styles.price}>৳{(Number(product.minimumPrice.amountMinor) / 100).toLocaleString("en-BD")}</Text><Text style={[styles.stock, stock === 0 && styles.outOfStock]}>{stock} in stock</Text></View><Text style={styles.sku}>{product.variants.map((item) => item.sku).slice(0, 2).join(" · ")}</Text></View></Pressable><View style={styles.cardActions}><Pressable onPress={() => router.push(`/vendor/products/${product.id}` as never)} style={styles.cardAction}><Ionicons color={colors.primary} name="eye-outline" size={17} /><Text style={styles.cardActionText}>View</Text></Pressable>{editable ? <Pressable onPress={() => router.push(`/vendor/products/edit/${product.id}` as never)} style={styles.cardAction}><Ionicons color={colors.primary} name="create-outline" size={17} /><Text style={styles.cardActionText}>Edit</Text></Pressable> : null}{editable ? <Pressable disabled={submit.isPending} onPress={() => submit.mutate(product.id)} style={styles.submit}><Text style={styles.submitText}>Submit</Text></Pressable> : null}</View></View>; })}</View>
    {!products.isLoading && !visible.length ? <View style={styles.empty}><Ionicons color={colors.primary} name="cube-outline" size={48} /><Text style={styles.emptyTitle}>{products.data?.length ? "No matching products" : "Create your first product"}</Text><Text style={styles.emptyCopy}>{products.data?.length ? "Try another search or status filter." : "Add a listing with category, pricing and opening stock."}</Text><Pressable onPress={() => router.push("/vendor/products/add")} style={styles.primary}><Text style={styles.primaryText}>Add product</Text></Pressable></View> : null}{submit.error ? <Text style={styles.error}>{submit.error.message}</Text> : null}
  </Screen>;
}

function Metric({ icon, label, value }: { icon: React.ComponentProps<typeof Ionicons>["name"]; label: string; value: number }) { return <View style={styles.metric}><View style={styles.metricIcon}><Ionicons color={colors.primary} name={icon} size={20} /></View><View><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricLabel}>{label}</Text></View></View>; }
const styles = StyleSheet.create({ summary: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, metric: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, flex: 1, flexDirection: "row", gap: spacing.sm, minWidth: 190, padding: spacing.md }, metricIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 42, justifyContent: "center", width: 42 }, metricValue: { color: colors.text, fontSize: 20, fontWeight: "900" }, metricLabel: { color: colors.muted, fontSize: 10, marginTop: 2 }, toolbar: { alignItems: "center", flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, search: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, flex: 1, flexDirection: "row", gap: 8, minWidth: 260, paddingHorizontal: 12 }, searchInput: { color: colors.text, flex: 1, minHeight: 46, outlineStyle: "none" } as never, secondary: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.md, borderWidth: 1, flexDirection: "row", gap: 6, minHeight: 46, paddingHorizontal: spacing.md }, secondaryText: { color: colors.primary, fontWeight: "900" }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, flexDirection: "row", gap: 6, justifyContent: "center", minHeight: 46, paddingHorizontal: spacing.md }, primaryText: { color: colors.surface, fontWeight: "900" }, filters: { flexDirection: "row", flexWrap: "wrap", gap: 6 }, filter: { alignItems: "center", borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, flexDirection: "row", gap: 6, paddingHorizontal: 11, paddingVertical: 8 }, filterActive: { backgroundColor: colors.navy, borderColor: colors.navy }, filterText: { color: colors.muted, fontSize: 10, fontWeight: "900" }, filterTextActive: { color: colors.surface }, filterCount: { backgroundColor: "#f1f5f9", borderRadius: radius.pill, color: colors.muted, fontSize: 8, fontWeight: "900", overflow: "hidden", paddingHorizontal: 6, paddingVertical: 3 }, filterCountActive: { backgroundColor: "rgba(255,255,255,.15)", color: colors.surface }, resultsHeader: { alignItems: "center", flexDirection: "row", justifyContent: "space-between" }, resultCount: { color: colors.text, fontSize: 16, fontWeight: "900" }, resultMeta: { color: colors.muted, fontSize: 10 }, grid: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, card: { backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, minWidth: 250, overflow: "hidden", width: "31.8%" }, media: { position: "relative" }, image: { aspectRatio: 1.35, backgroundColor: "#f8fafc", width: "100%" }, status: { backgroundColor: colors.navy, borderRadius: radius.pill, color: colors.surface, fontSize: 8, fontWeight: "900", overflow: "hidden", paddingHorizontal: 8, paddingVertical: 5, position: "absolute", right: 9, top: 9 }, rejected: { backgroundColor: colors.danger }, cardBody: { gap: 5, padding: spacing.md }, name: { color: colors.text, fontSize: 15, fontWeight: "900", minHeight: 38 }, brand: { color: colors.muted, fontSize: 10 }, priceRow: { alignItems: "center", flexDirection: "row", justifyContent: "space-between" }, price: { color: colors.accent, fontSize: 18, fontWeight: "900" }, stock: { color: colors.success, fontSize: 9, fontWeight: "800" }, outOfStock: { color: colors.danger }, sku: { color: colors.muted, fontSize: 9 }, cardActions: { alignItems: "center", borderTopColor: colors.border, borderTopWidth: 1, flexDirection: "row", gap: 4, padding: spacing.sm }, cardAction: { alignItems: "center", flexDirection: "row", gap: 4, padding: 7 }, cardActionText: { color: colors.primary, fontSize: 10, fontWeight: "900" }, submit: { backgroundColor: colors.primary, borderRadius: radius.sm, marginLeft: "auto", paddingHorizontal: 10, paddingVertical: 8 }, submitText: { color: colors.surface, fontSize: 9, fontWeight: "900" }, empty: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.xl, borderStyle: "dashed", borderWidth: 1, gap: spacing.sm, padding: 44 }, emptyTitle: { color: colors.text, fontSize: 20, fontWeight: "900" }, emptyCopy: { color: colors.muted, textAlign: "center" }, error: { color: colors.danger } });
